insert into public.exercise_translations (exercise_id, lang, title, description, cues, safety) values ('single_leg_balance', 'en', 'Single-Leg Balance Hold', 'Stand tall and lift one foot slightly. Use a chair for support if needed.', '["Look forward","Keep hips level","Breathe steadily"]'::jsonb, 'Hold onto a chair if balance feels unsteady.') on conflict (exercise_id, lang) do update set title = excluded.title, description = excluded.description, cues = excluded.cues, safety = excluded.safety;
